// Generated by OSL (@osl/backend-hono-trpc-vite). Sign-in providers beyond passwords (magic links, OAuth) and invites. Transport-neutral; the auth routes set the cookie.
// Do not edit: this file is rewritten on every osl generate.

import { createHash, randomBytes } from "node:crypto";
import { and, eq, gt } from "drizzle-orm";
import { db } from "./db/client";
import { users as identityTable, oslAuthTokens, teamInvites, teamMembers, teams, type TeamInvite, type NewTeamInvite, channelInvites, channelMembers, channels, type ChannelInvite, type NewChannelInvite, type User } from "./db/schema";
import { fail } from "./server/errors";
import { emailMode, inviteEmail, sendEmail } from "./email";
import type { Session } from "./server/auth";

/** Where the web app lives: magic links and invites point here and OAuth returns here (OSL_APP_URL) */
export const APP_URL = (process.env.OSL_APP_URL ?? "http://localhost:3000").replace(/\/$/, "");

const MAGIC_LINK_MINUTES = 10;
const OAUTH_STATE_MINUTES = 10;

export const PROVIDERS: { kind: string; name: string }[] = [
  { kind: "credentials", name: "credentials" },
  { kind: "magic_link", name: "magic_link" }
];

function hash(value: string): string {
  return createHash("sha256").update(value).digest("base64url");
}

/** The user with this email, created when the identity needs nothing but an email and a name. */
export async function findOrCreateByEmail(rawEmail: string, name?: string): Promise<User> {
  const email = rawEmail.trim().toLowerCase();
  const existing = await db.query.users.findFirst({ where: eq(identityTable.email, email) });
  if (existing) return existing;
  const [created] = await db
    .insert(identityTable)
    .values({ email: email, name: name ?? email.split("@")[0] })
    .returning();
  return created;
}

/**
 * Email a one-time sign-in link. Answers the token only when emails are captured (tests); otherwise null, and the
 * caller always reports success so addresses cannot be probed.
 */
export async function issueMagicLink(rawEmail: string): Promise<{ token: string; url: string } | null> {
  const email = rawEmail.trim().toLowerCase();
  const user = await db.query.users.findFirst({ where: eq(identityTable.email, email) });
  if (!user && !true) return null;
  const token = randomBytes(32).toString("base64url");
  await db.insert(oslAuthTokens).values({
    token_hash: hash(token),
    email,
    purpose: "magic_link",
    expires_at: new Date(Date.now() + MAGIC_LINK_MINUTES * 60_000)
  });
  const url = APP_URL + "/login/verify?token=" + encodeURIComponent(token);
  await sendEmail({
    to: email,
    subject: "Your sign-in link",
    text: "Sign in with this link (valid for " + MAGIC_LINK_MINUTES + " minutes): " + url
  });
  return emailMode() === "capture" ? { token, url } : null;
}

/**
 * Take the token (once) and answer its user, creating the user when the model allows. The link has proven the
 * address, so the invites waiting for it are accepted.
 */
export async function verifyMagicLink(token: string): Promise<{ user: User; accepted: Accepted[] }> {
  const [row] = await db.delete(oslAuthTokens).where(eq(oslAuthTokens.token_hash, hash(token))).returning();
  if (!row || row.purpose !== "magic_link" || row.expires_at.getTime() < Date.now()) fail(400, "invalid_token", "This link is invalid or has expired");
  const user = await findOrCreateByEmail(row.email);
  return { user, accepted: await acceptPending(user, row.email) };
}

// Invites. An invite is a row of an invite resource; its link carries a token the row keeps only the hash of.

/** What accepting an invite made: the row joined, the role given in it, and the tenant that row belongs to */
export type Accepted = { entity: string; id: string | number; role?: string; tenant: string | number | null };

/** What an invite shows whoever holds its link, before anyone has proven the address */
export type InviteLookup = {
  entity: string;
  name: string;
  role?: string;
  inviter: string;
  email: string;
  expires_at: string;
  account: boolean;
};

/** The part of a user the invite code reads */
type Invitee = Pick<User, "id" | "email">;

type FoundInvite =
  | { membership: "TeamMember"; row: TeamInvite }
  | { membership: "ChannelMember"; row: ChannelInvite };

/** A role's place in a list from most to least privileged; a role outside it, or none, ranks last */
function rankIn(roles: string[], role: string | null | undefined): number {
  const index = role == null ? -1 : roles.indexOf(role);
  return index < 0 ? roles.length : index;
}

/** Where the browser goes after a sign-in that accepted invites: the page that opens what was joined */
export function acceptedPath(first: Accepted): string {
  const params = new URLSearchParams({ entity: first.entity, id: String(first.id) });
  if (first.tenant !== null) params.set("tenant", String(first.tenant));
  return "/invite/accepted?" + params.toString();
}

function maskEmail(email: string): string {
  const at = email.lastIndexOf("@");
  return at < 1 ? "•••" : email[0] + "•••" + email.slice(at);
}

/** The invite a token belongs to, lapsed or not */
async function inviteOf(token: string): Promise<FoundInvite | null> {
  const tokenHash = hash(token);
  const [teamInvite] = await db.select().from(teamInvites).where(eq(teamInvites.token_hash, tokenHash));
  if (teamInvite) return { membership: "TeamMember", row: teamInvite };
  const [channelInvite] = await db.select().from(channelInvites).where(eq(channelInvites.token_hash, tokenHash));
  if (channelInvite) return { membership: "ChannelMember", row: channelInvite };
  return null;
}

/** The token's invite: 404 for a token that is unknown, used or revoked, 410 for one that has lapsed */
async function liveInvite(token: string): Promise<FoundInvite> {
  const found = await inviteOf(token);
  if (!found) fail(404, "not_found", "Not found");
  if (found.row.expires_at.getTime() <= Date.now()) fail(410, "invite_expired", "This invite has expired");
  return found;
}

async function parentOf(found: FoundInvite): Promise<{ entity: string; name: string; role?: string }> {
  switch (found.membership) {
    case "TeamMember": {
      const [parent] = await db.select({ name: teams.name }).from(teams).where(eq(teams.id, found.row.team_id));
      return { entity: "Team", name: String(parent?.name ?? ""), role: found.row.role ?? undefined };
    }
    case "ChannelMember": {
      const [parent] = await db.select({ name: channels.name }).from(channels).where(eq(channels.id, found.row.channel_id));
      return { entity: "Channel", name: String(parent?.name ?? ""), role: found.row.role ?? undefined };
    }
  }
}

/**
 * Send an invite to a Team. `before` is the resource's beforeCreate hook, handed the row as it will be
 * stored. Then, in order: the role ceiling, 409 for an address already invited or already a member, the row with
 * the token's hash, the mail. The row is kept only if the mail was handed to the adapter. The token is answered
 * only when emails are captured (tests).
 */
export async function issueTeamInvite(
  input: Pick<NewTeamInvite, "team_id" | "email" | "role">,
  session: Session,
  before: (values: NewTeamInvite) => Promise<NewTeamInvite> = async values => values
): Promise<{ row: TeamInvite; debug?: { token: string; url: string } }> {
  const token = randomBytes(32).toString("base64url");
  const me = session.user.id;
  const draft = await before({
    ...input,
    email: input.email.trim().toLowerCase(),
    invited_by: me,
    token_hash: hash(token),
    expires_at: new Date(Date.now() + 604800 * 1000)
  });
  const values = { ...draft, email: draft.email.trim().toLowerCase(), invited_by: me, token_hash: hash(token) };
  const parentId = values.team_id;

  // The ceiling: a member of the Team grants no role above the one they hold in it
  const [own] = await db
    .select({ role: teamMembers.role })
    .from(teamMembers)
    .where(and(eq(teamMembers.team_id, parentId), eq(teamMembers.user_id, me)));
  const ranked = ["owner", "admin", "member"];
  if (own && rankIn(ranked, values.role ?? "member") < rankIn(ranked, own.role)) {
    fail(403, "forbidden", "An invite cannot grant a role above your own");
  }

  const [waiting] = await db
    .select()
    .from(teamInvites)
    .where(and(eq(teamInvites.team_id, parentId), eq(teamInvites.email, values.email)));
  if (waiting && waiting.expires_at.getTime() > Date.now()) fail(409, "invite_exists", "An invite to this address is already waiting");
  const [account] = await db.select({ id: identityTable.id }).from(identityTable).where(eq(identityTable.email, values.email));
  if (account) {
    const [member] = await db
      .select({ user: teamMembers.user_id })
      .from(teamMembers)
      .where(and(eq(teamMembers.team_id, parentId), eq(teamMembers.user_id, account.id)));
    if (member) fail(409, "already_member", "This address already belongs to a member");
  }
  const [parent] = await db.select({ name: teams.name }).from(teams).where(eq(teams.id, parentId));
  if (!parent) fail(400, "invalid_reference", "A referenced row does not exist");

  // A lapsed invite to the address gives way to the new one
  const row = await db.transaction(async tx => {
    if (waiting) await tx.delete(teamInvites).where(eq(teamInvites.id, waiting.id));
    const [made] = await tx.insert(teamInvites).values(values).returning();
    return made;
  });
  const url = APP_URL + "/invite/" + encodeURIComponent(token);
  try {
    await sendEmail(
      inviteEmail({
        to: row.email,
        name: String(parent.name),
        inviter: String((session.user as Record<string, unknown>)["name"] ?? ""),
        role: row.role,
        url,
        expires: row.expires_at
      })
    );
  } catch (err) {
    await db.delete(teamInvites).where(eq(teamInvites.id, row.id));
    throw err;
  }
  return emailMode() === "capture" ? { row, debug: { token, url } } : { row };
}

/**
 * Send an invite to a Channel. `before` is the resource's beforeCreate hook, handed the row as it will be
 * stored. Then, in order: the role ceiling, 409 for an address already invited or already a member, the row with
 * the token's hash, the mail. The row is kept only if the mail was handed to the adapter. The token is answered
 * only when emails are captured (tests).
 */
export async function issueChannelInvite(
  input: Pick<NewChannelInvite, "channel_id" | "email" | "role">,
  session: Session,
  before: (values: NewChannelInvite) => Promise<NewChannelInvite> = async values => values
): Promise<{ row: ChannelInvite; debug?: { token: string; url: string } }> {
  const token = randomBytes(32).toString("base64url");
  const me = session.user.id;
  const draft = await before({
    ...input,
    email: input.email.trim().toLowerCase(),
    invited_by: me,
    token_hash: hash(token),
    expires_at: new Date(Date.now() + 604800 * 1000)
  });
  const values = { ...draft, email: draft.email.trim().toLowerCase(), invited_by: me, token_hash: hash(token) };
  const parentId = values.channel_id;

  // The ceiling: a member of the Channel grants no role above the one they hold in it
  const [own] = await db
    .select({ role: channelMembers.role })
    .from(channelMembers)
    .where(and(eq(channelMembers.channel_id, parentId), eq(channelMembers.user_id, me)));
  const ranked = ["admin", "member"];
  if (own && rankIn(ranked, values.role ?? "member") < rankIn(ranked, own.role)) {
    fail(403, "forbidden", "An invite cannot grant a role above your own");
  }

  const [waiting] = await db
    .select()
    .from(channelInvites)
    .where(and(eq(channelInvites.channel_id, parentId), eq(channelInvites.email, values.email)));
  if (waiting && waiting.expires_at.getTime() > Date.now()) fail(409, "invite_exists", "An invite to this address is already waiting");
  const [account] = await db.select({ id: identityTable.id }).from(identityTable).where(eq(identityTable.email, values.email));
  if (account) {
    const [member] = await db
      .select({ user: channelMembers.user_id })
      .from(channelMembers)
      .where(and(eq(channelMembers.channel_id, parentId), eq(channelMembers.user_id, account.id)));
    if (member) fail(409, "already_member", "This address already belongs to a member");
  }
  const [parent] = await db.select({ name: channels.name }).from(channels).where(eq(channels.id, parentId));
  if (!parent) fail(400, "invalid_reference", "A referenced row does not exist");

  // A lapsed invite to the address gives way to the new one
  const row = await db.transaction(async tx => {
    if (waiting) await tx.delete(channelInvites).where(eq(channelInvites.id, waiting.id));
    const [made] = await tx.insert(channelInvites).values(values).returning();
    return made;
  });
  const url = APP_URL + "/invite/" + encodeURIComponent(token);
  try {
    await sendEmail(
      inviteEmail({
        to: row.email,
        name: String(parent.name),
        inviter: String((session.user as Record<string, unknown>)["name"] ?? ""),
        role: row.role,
        url,
        expires: row.expires_at
      })
    );
  } catch (err) {
    await db.delete(channelInvites).where(eq(channelInvites.id, row.id));
    throw err;
  }
  return emailMode() === "capture" ? { row, debug: { token, url } } : { row };
}

/**
 * Make the TeamMember an invite stands for and use the invite up, in one transaction. A membership that
 * exists already is left as it is. Null when the invite was gone before this could take it.
 */
async function acceptTeamInvite(user: Invitee, invite: TeamInvite): Promise<Accepted | null> {
  const made = await db.transaction(async tx => {
    const [used] = await tx.delete(teamInvites).where(eq(teamInvites.id, invite.id)).returning({ id: teamInvites.id });
    if (!used) return null;
    const [member] = await tx.insert(teamMembers).values({ team_id: invite.team_id, user_id: user.id, role: invite.role }).onConflictDoNothing().returning();
    return { member };
  });
  if (!made) return null;
  return { entity: "Team", id: invite.team_id, role: invite.role ?? undefined, tenant: invite.team_id };
}

/** The tenant a Channel belongs to */
async function tenantOfChannel(id: ChannelInvite["channel_id"]): Promise<string | number | null> {
  const [hop0] = await db.select({ next: channels.team_id }).from(channels).where(eq(channels.id, id));
  return hop0?.next ?? null;
}

/**
 * Make the ChannelMember an invite stands for and use the invite up, in one transaction. A membership that
 * exists already is left as it is. Null when the invite was gone before this could take it.
 */
async function acceptChannelInvite(user: Invitee, invite: ChannelInvite): Promise<Accepted | null> {
  const made = await db.transaction(async tx => {
    const [used] = await tx.delete(channelInvites).where(eq(channelInvites.id, invite.id)).returning({ id: channelInvites.id });
    if (!used) return null;
    const [member] = await tx.insert(channelMembers).values({ channel_id: invite.channel_id, user_id: user.id, role: invite.role }).onConflictDoNothing().returning();
    return { member };
  });
  if (!made) return null;
  return { entity: "Channel", id: invite.channel_id, role: invite.role ?? undefined, tenant: await tenantOfChannel(invite.channel_id) };
}

/**
 * The one place an invite becomes a membership. It does nothing unless the proven email is the account's own; then
 * every live invite to that address is accepted, across all invited memberships. Answers what it accepted: the
 * invite whose token was used first, then the others, oldest first.
 */
export async function acceptPending(user: Invitee, provenEmail: string | null | undefined, usedToken?: string): Promise<Accepted[]> {
  const email = (provenEmail ?? "").trim().toLowerCase();
  if (!email || email !== String(user.email ?? "").trim().toLowerCase()) return [];
  const now = new Date();
  const first = usedToken ? hash(usedToken) : null;
  const done: { accepted: Accepted; first: boolean; at: number }[] = [];
  for (const invite of await db.select().from(teamInvites).where(and(eq(teamInvites.email, email), gt(teamInvites.expires_at, now)))) {
    const accepted = await acceptTeamInvite(user, invite);
    if (accepted) done.push({ accepted, first: invite.token_hash === first, at: invite.created_at.getTime() });
  }
  for (const invite of await db.select().from(channelInvites).where(and(eq(channelInvites.email, email), gt(channelInvites.expires_at, now)))) {
    const accepted = await acceptChannelInvite(user, invite);
    if (accepted) done.push({ accepted, first: invite.token_hash === first, at: invite.created_at.getTime() });
  }
  done.sort((a, b) => Number(b.first) - Number(a.first) || a.at - b.at);
  return done.map(entry => entry.accepted);
}

/** A password proves nothing about a mailbox, so a password sign-in accepts only with a live token for its own address. */
export async function acceptWithToken(user: Invitee, token: string): Promise<Accepted[]> {
  const found = await inviteOf(token);
  if (!found || found.row.expires_at.getTime() <= Date.now()) return [];
  return acceptPending(user, found.row.email, token);
}

/** GET /api/auth/invites/{token}: what the landing page shows. It never accepts, because mail scanners open links. */
export async function lookupInvite(token: string): Promise<InviteLookup> {
  const found = await liveInvite(token);
  const [inviter] = await db.select({ name: identityTable.name }).from(identityTable).where(eq(identityTable.id, found.row.invited_by));
  const [account] = await db.select({ id: identityTable.id }).from(identityTable).where(eq(identityTable.email, found.row.email));
  return {
    ...(await parentOf(found)),
    inviter: String(inviter?.name ?? ""),
    email: maskEmail(found.row.email),
    expires_at: found.row.expires_at.toISOString(),
    account: Boolean(account)
  };
}

/**
 * POST /api/auth/invites/{token}/accept. A session under the invite's email accepts; one under another email is
 * refused, and nothing changes. Without a session the token never signs anyone into an account that exists: it
 * asks for a sign-in. Where the address has no account, `create` makes it (the token has proven the address), and
 * the caller signs it in.
 */
export async function acceptInvite(
  token: string,
  userId: User["id"] | null,
  create: (email: string) => Promise<User>
): Promise<{ accepted: Accepted[]; created: User | null }> {
  const found = await liveInvite(token);
  const email = found.row.email;
  if (userId !== null) {
    const [me] = await db.select().from(identityTable).where(eq(identityTable.id, userId));
    if (!me || String(me.email ?? "").trim().toLowerCase() !== email) fail(403, "invite_email_mismatch", "This invite is for another address");
    return { accepted: await acceptPending(me, email, token), created: null };
  }
  const [account] = await db.select({ id: identityTable.id }).from(identityTable).where(eq(identityTable.email, email));
  if (account) fail(401, "sign_in_required", "Sign in to accept this invite");
  const created = await create(email);
  return { accepted: await acceptPending(created, email, token), created };
}
